Atomic - Compare-and-Swap.ejemplo:
// Bucle CAS en C++ (std::atomic) para incrementar de forma lock-free
std::atomic<int> counter{0};
int old_val = counter.load(std::memory_order_relaxed);
while (!counter.compare_exchange_weak(
           old_val, old_val + 1,
           std::memory_order_release,
           std::memory_order_relaxed)) {
  // old_val se actualiza automaticamente con el valor actual si falla
}

Barrier.ejemplo:
// C++20 std::barrier con 4 hilos y 2 fases
std::barrier sync_point(4);
void worker(int id) {
  fase_uno(id);
  sync_point.arrive_and_wait(); // espera a los 4 hilos
  fase_dos(id);
}

