Coroutines - green threads.ejemplo:
// Go: miles de goroutines multiplexadas sobre pocos hilos del kernel
for _, url := range urls {
  go func(u string) {
    resp, _ := http.Get(u) // se suspende en epoll sin bloquear el OS thread
    procesar(resp)
  }(url)
}

